  'editor.pers.animFlote':
    'मूवमेंट किरदार की सामान्य ऊपर-नीचे वाली हरकत की जगह लेता है; हाथ हिलाने वाला अभिवादन बना रहता है।',
  'editor.pers.animSinPiezas': 'पोज़ वाले एनिमेशन बनाने के लिए, «शरीर» टैब में 3D पुर्ज़ों से शरीर बनाएं।',
  'room.cocina.desc': 'पोषण: भोजन, मैक्रोज़, पानी और अपनी साप्ताहिक योजना दर्ज करें।',
  'room.ejercicio.desc': 'ताकत, सहनशक्ति और लचीलेपन की दिनचर्याएं, लक्ष्यों के साथ।',
  'room.recamara.desc': 'अपने आराम को ट्रैक करें और अपनी निजी यादों की डायरी लिखें।',
  'room.descanso.desc': 'आपकी नींद, रात के आसमान जैसी: समय-सारणी, अलार्म, स्कोर और रात की डायरी।',
  'room.anecdotario.desc': 'आपकी निजी डायरी: फ़ोटो के साथ यादें और रोज़ का मूड।',
  'room.despacho.desc':
    'फ़ाइनेंस: खर्च और आय (स्थायी और परिवर्तनशील) वाला बजट, लक्ष्य (वित्तीय कैलकुलेटर, बचत/निवेश, कर्ज़) सिमुलेटर के साथ, और लाइव मार्केट।',
  'room.biblioteca.desc': 'बातचीत वाला विश्वकोश: AI चैट, विकी एंट्री और स्टडी सेशन।',
  'room.entretenimiento.desc': 'फ़िल्मों, सीरीज़, किताबों और बोर्ड गेम्स का संग्रह।',
  'room.sala.desc': 'यात्राओं की योजना बनाएं: यात्रा-कार्यक्रम, खर्च, चेकलिस्ट और विशलिस्ट।',
  'room.jardin.desc': 'शांति: निर्देशित ध्यान, सांस लेने का अभ्यास और आभार डायरी।',
  'room.garage.desc': 'आपके वाहनों का रखरखाव और उनकी सर्विस।',
  'room.diario.desc': 'श्रेणियों के हिसाब से रोज़ की खबरों का हब।',
  'room.hobbies.desc': 'आपके शौक और क्रिएटिव प्रोजेक्ट्स।',
  'room.idiomas.desc': 'भाषाएं सीखें: AI ट्यूटर, स्पेस्ड-रिपिटिशन शब्दावली, स्तर के अनुसार पाठ्यक्रम और अभ्यास।',
  'room.calendario.desc': 'आपका कैलेंडर: दिन, हफ़्ते और महीने के हिसाब से इवेंट और दिनचर्याएं।',
  'room.caminos.desc': 'नक्शे पर रेस ट्रैक, रेलवे पटरियां और रोलर कोस्टर बनाएं।',
  'room.canchas.desc': 'नक्शे पर फ़ुटबॉल, टेनिस, बास्केटबॉल और बेसबॉल के मैदान रखें।',
  'room.huerto.desc': 'क्यारियां तैयार करें, फ़सलें बोएं, उन्हें पानी दें और असली समय में फ़सल काटें।',
  'room.granja.desc': 'मुर्गियां, सूअर, बकरियां, भेड़ें, गायें और घोड़े पालें, और उसी एडिटर में उनका चारा उगाएं।',
  'room.ideas.desc':
    'आपकी आइडिया डायरी और ब्रेनस्टॉर्मिंग, फ़्री कैनवस पर दस कॉन्सेप्ट-मैप फ़ॉर्मैट (माइंड मैप, ट्री, टाइमलाइन, साइकल, पिरामिड, वेन…) और फ़ैसला लेने के लिए आठ डायग्राम (पक्ष-विपक्ष, फ़ोर्स फ़ील्ड, SWOT, आइज़नहावर, डिसीज़न ट्री, टियर लिस्ट, वेटेड डिसीज़न मैट्रिक्स और इशिकावा), हाथ से या AI के साथ।',
  'room.metas.desc':
    'पूरे घर से आपने जो ठाना है, वह सब: लक्ष्यों की सूची उनके उप-लक्ष्यों और चरणों के साथ, हर एक के लिए AI जो योजनाएं सुझाता है (तारीख वाले चरण जो असली उप-लक्ष्य बन जाते हैं), और वह समय-सारणी जहां हर चीज़ समय की धुरी पर अपनी अवधि घेरती है।',
  'room.computo.desc':
    'कंप्यूटिंग कक्ष: फ़ॉर्मूला बुक के साथ साइंटिफ़िक कैलकुलेटर (गणित, भौतिकी और रसायन शामिल और संपादन-योग्य) और आठ मोड — चार तरह का प्लॉटर (2D, ध्रुवीय, पैरामेट्रिक और 3D सतह), बाइनरी और हेक्साडेसिमल, मैट्रिक्स, समीकरण-तंत्र, इकाई बदलाव, टिप और त्रैराशिक; और Excel व PDF में एक्सपोर्ट होने वाली स्प्रेडशीट।',
