  'constructor.cuarto.hintPincel':
    'किसी खाली सेल पर टैप करके उस आकार का कमरा बनाएं। घुमाने के लिए उसी सेल पर फिर टैप करें और आख़िर में मिटाने के लिए भी। किसी कमरे की सेल पर टैप करके उसका आकार बदलें। महीन ग्रिड (ऊपर दाईं ओर) से ¼ सेल के कोने काटे जाते हैं।',
