  'tut.appSinCuarto':
    'यह ऐप अभी किसी कमरे में नहीं है, इसलिए इसे यहीं से समझाता हूं। इसे इस्तेमाल करने के लिए, मेनू › टेम्पलेट में असाइन करें।',
  'tut.errorCarga': 'यह ट्यूटोरियल लोड नहीं हो सका। अपना कनेक्शन जांचें और फिर से कोशिश करें।',
  'tut.preparandoDemo': 'उस ऐप का साल डेमो घर में तैयार किया जा रहा है; टूर कुछ सेकंड में शुरू होगा…',
  'tut.selector.titulo': 'आप कौन-सा ट्यूटोरियल देखना चाहते हैं?',
  'tut.selector.hint': 'पीले रंग में हाइलाइट किए गए ज़ोन को टैप करें, या सामान्य वाले से शुरू करें।',
  'tut.selector.general': 'सामान्य ट्यूटोरियल',
  'tut.selector.cancelar': 'रद्द करें',
